import { getHandler as baseGetHandler, setHandler as baseSetHandler } from '@weavix/sdk-core';
import type { GetDataResultMap, HandlerFunction, Handlers } from './types';

/**
 * Регистрирует обработчик. Тип возвращаемого значения задаётся слотом (GetDataResultMap).
 */
export function setHandler<TSlot extends keyof GetDataResultMap>(
    name: 'getData',
    handler: () => GetDataResultMap[TSlot],
): void;
export function setHandler<TKey extends keyof Handlers>(
    name: TKey,
    handler: HandlerFunction<TKey>,
): void;
export function setHandler(name: string, handler: (...args: unknown[]) => unknown): void {
    baseSetHandler(name, handler);
}

/**
 * Возвращает обработчик getData. При указании TSlot — () => GetDataResultMap[TSlot].
 */
export function getHandler<TSlot extends keyof GetDataResultMap>(
    name: 'getData',
): (() => GetDataResultMap[TSlot]) | undefined;
export function getHandler<TKey extends keyof Handlers>(
    name: TKey,
): HandlerFunction<TKey> | undefined;
export function getHandler(name: string): ((...args: unknown[]) => unknown) | undefined {
    return baseGetHandler(name);
}
